routes = []
for prefix, uri_template, methods, resource in router._lookup_table:
    methods_info = []
    for method in methods:
        if method == 'HEAD' and 'GET' in methods:
            continue
        fn = getattr(resource, 'on_' + method.lower(), None)
        if fn:
            source_info = _get_source_info(fn)
            methods_info.append(
                RouteMethodInfo(
                    method, source_info, fn.__name__, _is_internal(fn)
                )
            )
    if methods_info:
        class_source_info, class_name = _get_source_info_and_name(resource)
        route = RouteInfo(
            prefix + uri_template,
            class_name,
            class_source_info,
            methods_info,
        )
        routes.append(route)
return routes

