if not isinstance(s, str):
    return s

res = []
b64_buffer = []
for c in s:
    if ord(c) & 0x80:
        if b64_buffer:
            res.append("&" + base64_utf7_encode(b64_buffer).decode("ascii") + "-")
            b64_buffer = []
        res.append(c)
    elif c == "&":
        if b64_buffer:
            res.append("&" + base64_utf7_encode(b64_buffer).decode("ascii") + "-")
            b64_buffer = []
