    if i == 0 or j == 0:
        return []
    elif x[i - 1] == y[j - 1]:
        return _recon(i - 1, j - 1) + [(x[i - 1], i)]
    elif table[i - 1, j] > table[i, j - 1]:
        return _recon(i - 1, j)
