    ".".join(parts[i:])
    for i in range(len(parts))
    if d.get(".".join(parts[i:])) is not None
]

if not root_keys:
    return default

root_key = max(root_keys, key=len)

if not isinstance(d.get(root_key), dict):
    return default

subpath = path[len(root_key) + 1 :]
return find_nested_value(d.get(root_key), subpath, default)

if path in d:
    return d[path]

parts = path.split(".")
root = ".".join(parts[:-1])
subpath = parts[-1]
root_keys = [root] + [root[:-i] for i in range(1, len(parts))]
root_keys.reverse()

for root_key in root_keys:
    if root_key in d:
        if isinstance(d[root_key], collections_abc.Mapping):
            return find_nested_value(d[root_key], subpath, default)
        else:
            return default

return default

