plugins = pm.list_plugin_distinfo()
output = []
for name, (plugin, dist) in plugins:
    hooks = {}
    for hook in pm.get_hookcallers(plugin):
        hooks[hook.name] = {}
        for method in dir(hook):
            if not method.startswith("__"):
                hooks[hook.name][method] = getattr(hook, method).__doc__
    out = {
        "name": name,
        "hooks": hooks,
    }
    if dist:
        out.update(
            {
                "version": dist.version,
                "project_name": dist.project_name,
            }
        )
    output.append(out)
return output

