def helper(string, start, repeat_length):
    if start > (len(string) - 1):
        return None
    if start + repeat_length > len(string):
        return None
    repeated_string = string[start:start + repeat_length]
    for i in range(start + repeat_length, len(string)):
        if string[i] != repeated_string[i - start]:
            return None
    return {'base_token': repeated_string, 'base_token_guesses':
        most_guessable_match_sequence(repeated_string,
                                     _ranked_dictionaries)}

