    names_in_certificate.extend(certificate.extensions.get_extension_for_oid(cryptography.x509.oid.ExtensionOID.SUBJECT_ALTERNATIVE_NAME).value)
except cryptography.x509.ExtensionNotFound:
    names_in_certificate = []

names_in_certificate_as_dict = {}
for name_in_certificate in names_in_certificate:
    try:
        names_in_certificate_as_dict[name_in_certificate.value] = name_in_certificate.value
    except AttributeError:
        for name_part in name_in_certificate.value.get_attributes_for_oid(
            cryptography.x509.oid.NameOID.COMMON_NAME
        ):
            names_in_certificate_as_dict[name_part.value] = name_part.value

for name_in_certificate in names_in_certificate_as_dict.values():
    try:
        match_hostname(name_in_certificate, server_hostname)
        return True
    except CertificateError:
        pass

return False

try:
    names_to_check = [server_hostname]
    try:
        # Attempt to get the Common Name from the certificate
        common_name_list = certificate.subject.get_attributes_for_oid(NameOID.COMMON_NAME)
        common_name_list = [str(common_name.value) for common_name in common_name_list]
        names_to_check.extend(common_name_list)
    except ExtensionNotFound:
        # No common name
        pass

    # Attempt to get the Subject Alternative Names from the certificate
    try:
        san_list = certificate.extensions.get_extension_for_oid(ExtensionOID.SUBJECT_ALTERNATIVE_NAME)
        san_list = san_list.value
        names_to_check.extend(san_list)
    except ExtensionNotFound:
        # No SAN
        pass

    # Check if any of the names match the server_hostname
    for name_to_check in names_to_check:
        try:
            match_hostname(name_to_check, server_hostname)
            return True
        except CertificateError:
            pass

    return False
except ValueError:
    # Cryptography could not parse the certificate https://github.com/nabla-c0d3/sslyze/issues/495
    return False
